document.addEventListener("DOMContentLoaded",()=>{const e={C:document.getElementById("temp-celsius"),F:document.getElementById("temp-fahrenheit"),K:document.getElementById("temp-kelvin")};function t(t,n){if(n===""||isNaN(n)){Object.values(e).forEach(e=>e.value="");return}let s;switch(t){case"C":s=n;break;case"F":s=(n-32)*5/9;break;case"K":s=n-273.15;break}t!=="C"&&(e.C.value=parseFloat(s.toFixed(4))),t!=="F"&&(e.F.value=parseFloat((s*9/5+32).toFixed(4))),t!=="K"&&(e.K.value=parseFloat((s+273.15).toFixed(4)))}Object.keys(e).forEach(n=>{e[n].addEventListener("input",e=>{const s=e.target.value===""?"":parseFloat(e.target.value);t(n,s)})})})